'use client';
// TDM-97: 3D digital twin of the I2RT YAM, driven by RobotLiveState (E15 robot view contract,
// docs/WORKER_GUIDE.md). Purely presentational: no data fetching. Lazy-load it with
// next/dynamic + ssr:false (RobotView does).
//
// Model: the SDK's own YAM v1 + linear_4310 (i2rt-robotics/i2rt@120c3c8, MIT), the same model
// yam_kinematics.py and the MuJoCo sim use: kinematic tree in ./yamModel.ts, decimated meshes in
// /robot/yam/yam.glb (both generated by spikes/tdm-97/build_yam_assets.py). The FK spot check is
// apps/web/test/robotview-twin-fk.test.ts.
//
// Scene: a scene spec v1 (lib/robotview/scene.ts, TDM-104's schema) gives the table, objects
// (box / cylinder / sphere) and regions; live object poses come from state.scene.objects[id], with
// the original cube / plate fields as fallback. Without a spec, the legacy cube / plate are drawn.
//
// Cameras: `camera` = 'top' | 'side' | 'front' | 'wrist' (TWIN_CAMERAS) or the id of a spec camera,
// so several twins can show the same scene from different angles at once.
//
// Frames: world (table) frame, z up, metres, inside one group that maps it onto three.js's y-up
// world: (x, y, z) -> three (x, z, -y). The arm sits in it at spec.robot.mount (identity in the sim).
import { CameraControls, Environment, Grid, Lightformer, Line, PerformanceMonitor, RoundedBox, useGLTF } from '@react-three/drei';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import { Suspense, useCallback, useEffect, useMemo, useRef, useState, type MutableRefObject } from 'react';
import * as THREE from 'three';
import { toCreasedNormals } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import { legacyScene, livePose, sceneLive, type SceneCamera, type SceneObject, type SceneRegion, type SceneSpecV1, type SceneTable } from '@/lib/robotview/scene';
import type { RobotLiveState, Vec3 } from '@/lib/robotview/types';
import type { TwinPerf } from '@/lib/teleop/viewQuality';
import { usePageVisible } from '@/lib/teleop/useViewQuality';
import { createYamKinematics, YAM_REST, type Mat4 } from './yamFk';
import { YAM_BODIES, YAM_GRASP_SITE, YAM_MODEL, YAM_WRIST_CAMERA, type YamBody } from './yamModel';

export type TwinCamera = 'top' | 'side' | 'front' | 'wrist';
/** @deprecated use TwinCamera; kept for the E15 contract's `preset` prop. */
export type TwinPreset = TwinCamera;

export interface RobotTwin3DProps {
  state: RobotLiveState | null;
  /** Which view: a built-in camera (TWIN_CAMERAS) or a spec camera id. Default 'top'. */
  camera?: TwinCamera | string;
  /** Same as `camera` (the original contract prop); `camera` wins when both are set. */
  preset?: TwinCamera | string;
  /** Scene spec v1 to draw (table, objects, regions, cameras). Omit: legacy cube / plate from the feed. */
  spec?: SceneSpecV1 | null;
  /** false = fixed camera, no orbit (small multi-view tiles). Default true. */
  controls?: boolean;
  /** The sim robot: draws the scene's engineering grid on the table (RobotView owns the SIMULATED label). */
  sim?: boolean;
  /** Joint-space targets (rad, >= 6 per row) to draw as a ghost: tool-point path + the arm at the last row. */
  ghost?: number[][];
  className?: string;
  /** Render budget (lib/teleop/viewQuality.ts twinPerf): pixel-ratio cap, shadows, frame-rate cap. Omit: full quality. */
  perf?: TwinPerf | null;
}

const GLB_URL = '/robot/yam/yam.glb';
const KIN = createYamKinematics(YAM_MODEL);

// ---------------------------------------------------------------------------------------- palette
// Dusk studio: a cool slate cyclorama the arm sits in, a warm stone bench, graphite + bead-blasted
// aluminium links. Colour carries meaning only where it matters: amber = the safety envelope,
// ice blue = what the policy intends next, red = e-stop. Scene objects keep their spec colours (the
// MuJoCo scene's), so the twin and the sim camera read as the same scene.
const C = {
  stage: '#2b323c',
  stageSim: '#2f2c40', // the sim frame is violet (RobotView); the stage leans that way too
  floor: '#232931',
  bench: '#bdb6a9',
  benchEdge: '#9f9788',
  graphite: '#2a2e35',
  aluminium: '#b6bbc2',
  sensor: '#17191d',
  envelope: '#f0a63a',
  intent: '#8cc2ff',
  estop: '#ff4d4f',
};

/** Which links are anodised graphite and which are bare aluminium (alternating reads as machined). */
const FINISH: Record<string, 'graphite' | 'aluminium' | 'sensor'> = {
  base: 'graphite',
  link1: 'aluminium',
  link2: 'graphite',
  link3: 'graphite',
  link4: 'aluminium',
  link5: 'graphite',
  gripper: 'graphite',
  tip_left: 'aluminium',
  tip_right: 'aluminium',
  wrist_cam_mount: 'sensor',
};

// ---------------------------------------------------------------------------------------- cameras
// World frame (z up). `top` is the MuJoCo sim's `top` camera (mujoco_scene.SceneSpec.top_pos /
// top_target, fovy 52): raised above the bench and looking down at the work area like a mounted
// camera, so the twin lines up with the sim's camera pane. A spec camera with the same id wins.
// `wrist` rides the D405 on the flange (the sim's `wrist` camera) and so follows the end effector.
export const TWIN_CAMERAS: Record<TwinCamera, SceneCamera> = {
  top: { id: 'top', pos: [0.86, -0.5, 0.58], target: [0.27, 0.03, 0.06], fovy: 52 },
  side: { id: 'side', pos: [0.3, -1.05, 0.3], target: [0.28, 0, 0.13], fovy: 42 },
  front: { id: 'front', pos: [1.2, 0.02, 0.42], target: [0.22, 0, 0.14], fovy: 42 },
  wrist: { id: 'wrist', fovy: YAM_WRIST_CAMERA.fovy, attach: 'wrist' },
};

/** A spec camera of that id, else the built-in one, else `top`. */
export function resolveTwinCamera(id: string | undefined, spec?: SceneSpecV1 | null): SceneCamera {
  const key = id || 'top';
  const fromSpec = spec?.cameras?.find((c) => c.id === key);
  if (fromSpec && (fromSpec.attach === 'wrist' || (fromSpec.pos && fromSpec.target))) return fromSpec;
  return TWIN_CAMERAS[key as TwinCamera] ?? TWIN_CAMERAS.top;
}

const DEFAULT_TABLE: SceneTable = { size: [0.96, 0.96], center: [0.3, 0], top_z: 0, thickness: 0.04 };

const r2t = (v: readonly number[]): [number, number, number] => [v[0], v[2], -v[1]];
const ROBOT_TO_THREE = new THREE.Matrix4().makeRotationX(-Math.PI / 2);
const quatWxyz = (q: readonly number[]) => new THREE.Quaternion(q[1], q[2], q[3], q[0]);

// ---------------------------------------------------------------------------------------- smoothing
// State arrives at 10-30 Hz; the arm is drawn every frame by easing towards the latest sample
// (critically damped first-order, ~60 ms time constant), so motion is continuous without lagging.
const EASE_PER_S = 16;

interface ObjPose {
  p: THREE.Vector3;
  q: THREE.Quaternion;
  /** A live pose has arrived for it (else it sits at the spec pose, or is hidden on a live robot). */
  live: boolean;
}

interface Smoothed {
  init: boolean;
  q: number[];
  gripper: number;
  objects: Map<string, ObjPose>;
  ghostQ: number[] | null;
}

function newSmoothed(): Smoothed {
  return { init: false, q: [...YAM_REST], gripper: 1, objects: new Map(), ghostQ: null };
}

function specPose(o: SceneObject): { p: THREE.Vector3; q: THREE.Quaternion } {
  const q = o.pose.quat ?? [1, 0, 0, 0];
  return { p: new THREE.Vector3(...o.pose.pos), q: quatWxyz(q).normalize() };
}

function Driver({ stateRef, ghostRef, smooth, objectsRef }: {
  stateRef: MutableRefObject<RobotLiveState | null>;
  ghostRef: MutableRefObject<number[] | null>;
  smooth: Smoothed;
  objectsRef: MutableRefObject<SceneObject[]>;
}) {
  const tmpV = useMemo(() => new THREE.Vector3(), []);
  const tmpQ = useMemo(() => new THREE.Quaternion(), []);
  useFrame((_, dt) => {
    const s = stateRef.current;
    const a = smooth.init ? 1 - Math.exp(-EASE_PER_S * Math.min(dt, 0.1)) : 1;
    if (s) {
      for (let i = 0; i < 6; i++) {
        const t = s.joints[i];
        if (Number.isFinite(t)) smooth.q[i] += (t - smooth.q[i]) * a;
      }
      if (Number.isFinite(s.gripper)) smooth.gripper += (s.gripper - smooth.gripper) * a;
      smooth.init = true;
    }
    const live = sceneLive(s);
    for (const o of objectsRef.current) {
      let cur = smooth.objects.get(o.id);
      if (!cur) {
        const sp = specPose(o);
        cur = { p: sp.p, q: sp.q, live: false };
        smooth.objects.set(o.id, cur);
      }
      const lp = livePose(live, o.id);
      if (!lp) continue;
      if (o.fixed) {
        // TDM-104: fixed objects (plates, fixtures) never move: keep the spec pose (the sim reports a plate's
        // body origin, its bottom, while the render pose is its centre)
        cur.live = true;
        continue;
      }
      // the legacy `plate` field carries the plate's top surface height; keep the spec's z for it
      const z = o.id === 'plate' && !live?.objects?.plate ? o.pose.pos[2] : lp.pos[2];
      const k = cur.live ? a : 1;
      cur.p.lerp(tmpV.set(lp.pos[0], lp.pos[1], z), k);
      if (lp.quat) cur.q.slerp(tmpQ.set(lp.quat[1], lp.quat[2], lp.quat[3], lp.quat[0]).normalize(), k);
      cur.live = true;
    }
    const g = ghostRef.current;
    if (g) {
      if (!smooth.ghostQ) smooth.ghostQ = [...g];
      else for (let i = 0; i < 6; i++) smooth.ghostQ[i] += (g[i] - smooth.ghostQ[i]) * a;
    } else smooth.ghostQ = null;
  }, -1);
  return null;
}

// ---------------------------------------------------------------------------------------- the arm
type Geoms = Record<string, THREE.BufferGeometry[]>; // body name -> its mesh geometries

const GEOM_CACHE = new WeakMap<object, Geoms>(); // shared by the arm and its ghost

function useArmGeometries(): Geoms {
  const gltf = useGLTF(GLB_URL);
  return useMemo(() => {
    const hit = GEOM_CACHE.get(gltf.scene);
    if (hit) return hit;
    const out: Geoms = {};
    gltf.scene.traverse((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh) return;
      const body = m.name.split('__')[0];
      // CAD meshes: crease at 35 deg so flats stay flat and fillets stay round.
      const g = toCreasedNormals(m.geometry, (35 * Math.PI) / 180);
      (out[body] ??= []).push(g);
    });
    GEOM_CACHE.set(gltf.scene, out);
    return out;
  }, [gltf]);
}

// The ghost draws only the hand (where the policy is taking it): a whole translucent arm on top of
// the real one reads as a smear.
const GHOST_BODIES: ReadonlySet<string> = new Set(['gripper', 'tip_left', 'tip_right', 'wrist_cam_mount']);

const CHILDREN: Record<string, YamBody[]> = {};
for (const b of YAM_BODIES) (CHILDREN[b.parent] ??= []).push(b);

function Body({ body, geoms, materials, jointRefs, graspRef, shadows, only }: {
  body: YamBody;
  only?: ReadonlySet<string>;
  geoms: Geoms;
  materials: Record<string, THREE.Material>;
  jointRefs: MutableRefObject<Record<string, THREE.Group | null>>;
  graspRef?: MutableRefObject<THREE.Object3D | null>;
  shadows: boolean;
}) {
  const quat = useMemo(() => quatWxyz(body.quat), [body.quat]);
  return (
    <group position={body.pos as unknown as [number, number, number]} quaternion={quat}>
      <group ref={(g) => { if (body.joint) jointRefs.current[body.joint.name] = g; }}>
        {(!only || only.has(body.name) ? (geoms[body.name] ?? []) : []).map((g, i) => (
          <mesh key={i} geometry={g} material={materials[FINISH[body.name] ?? 'graphite']} castShadow={shadows} />
        ))}
        {graspRef && body.name === YAM_GRASP_SITE.body && (
          <object3D ref={graspRef} position={YAM_GRASP_SITE.pos as unknown as [number, number, number]} quaternion={quatWxyz(YAM_GRASP_SITE.quat)} />
        )}
        {(CHILDREN[body.name] ?? []).map((c) => (
          <Body key={c.name} body={c} geoms={geoms} materials={materials} jointRefs={jointRefs} graspRef={graspRef} shadows={shadows} only={only} />
        ))}
      </group>
    </group>
  );
}

function Arm({ read, materials, graspRef, shadows = true, only }: {
  /** Draw only these bodies' meshes (the chain is still posed in full). */
  only?: ReadonlySet<string>;
  read: () => { q: number[]; gripper: number } | null;
  materials: Record<string, THREE.Material>;
  graspRef?: MutableRefObject<THREE.Object3D | null>;
  shadows?: boolean;
}) {
  const geoms = useArmGeometries();
  const jointRefs = useRef<Record<string, THREE.Group | null>>({});
  const root = useRef<THREE.Group>(null);
  const axes = useMemo(() => {
    const m: Record<string, { type: 'hinge' | 'slide'; axis: THREE.Vector3 }> = {};
    for (const b of YAM_BODIES) if (b.joint) m[b.joint.name] = { type: b.joint.type, axis: new THREE.Vector3(...b.joint.axis).normalize() };
    return m;
  }, []);
  useFrame(() => {
    const r = read();
    if (root.current) root.current.visible = !!r;
    if (!r) return;
    const vals = KIN.jointValues(r.q, r.gripper);
    for (const [name, j] of Object.entries(axes)) {
      const g = jointRefs.current[name];
      if (!g) continue;
      const v = vals[name] ?? 0;
      if (j.type === 'hinge') g.quaternion.setFromAxisAngle(j.axis, v);
      else g.position.copy(j.axis).multiplyScalar(v);
    }
  });
  return (
    <group ref={root}>
      {(CHILDREN.world ?? []).map((b) => (
        <Body key={b.name} body={b} geoms={geoms} materials={materials} jointRefs={jointRefs} graspRef={graspRef} shadows={shadows} only={only} />
      ))}
    </group>
  );
}

function useArmMaterials() {
  return useMemo(() => {
    const solid = {
      graphite: new THREE.MeshPhysicalMaterial({ color: C.graphite, metalness: 0.35, roughness: 0.38, clearcoat: 0.6, clearcoatRoughness: 0.28, envMapIntensity: 1.4 }),
      aluminium: new THREE.MeshPhysicalMaterial({ color: C.aluminium, metalness: 0.75, roughness: 0.3, envMapIntensity: 1.6 }),
      sensor: new THREE.MeshPhysicalMaterial({ color: C.sensor, metalness: 0.2, roughness: 0.25, clearcoat: 0.8 }),
    };
    const ghostMat = new THREE.MeshStandardMaterial({
      color: C.intent, emissive: C.intent, emissiveIntensity: 0.6, transparent: true, opacity: 0.28, depthWrite: true, roughness: 0.6,
    });
    const ghost = { graphite: ghostMat, aluminium: ghostMat, sensor: ghostMat };
    return { solid, ghost };
  }, []);
}

// ---------------------------------------------------------------------------------------- scene
function Bench({ table, sim }: { table: SceneTable; sim: boolean }) {
  // Default: the MuJoCo scene's table, 0.96 m square top centred at x = 0.30, top surface at z = 0.
  const [sx, sy] = table.size;
  const [cx, cy] = table.center;
  const th = table.thickness ?? 0.04;
  const tableZ = table.top_z;
  const top = r2t([cx, cy, tableZ - th / 2]);
  const legs = [[-1, -1], [-1, 1], [1, -1], [1, 1]].map(([i, j]) => [cx + i * (sx / 2 - 0.04), cy + j * (sy / 2 - 0.04)]);
  return (
    <group>
      <RoundedBox args={[sx, th, sy]} radius={Math.min(0.008, th / 3)} smoothness={3} position={top} receiveShadow>
        <meshStandardMaterial color={table.color ?? C.bench} roughness={0.88} metalness={0} />
      </RoundedBox>
      {legs.map(([x, y], i) => (
        <mesh key={i} position={r2t([x, y, tableZ - 0.39])}>
          <boxGeometry args={[0.05, 0.7, 0.05]} />
          <meshStandardMaterial color={C.graphite} roughness={0.6} metalness={0.4} />
        </mesh>
      ))}
      {sim && (
        <Grid
          position={r2t([cx, cy, tableZ + 0.0006])}
          args={[sx, sy]}
          cellSize={0.05}
          cellThickness={0.5}
          cellColor={C.benchEdge}
          sectionSize={0.25}
          sectionThickness={1}
          sectionColor="#a39bc4"
          fadeDistance={6}
          followCamera={false}
        />
      )}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, tableZ - 0.74, 0]} receiveShadow>
        <planeGeometry args={[12, 12]} />
        <meshStandardMaterial color={C.floor} roughness={1} />
      </mesh>
    </group>
  );
}

function Envelope({ ws, estop }: { ws: NonNullable<RobotLiveState['workspace']>; estop: boolean }) {
  const size: Vec3 = [ws.max[0] - ws.min[0], ws.max[1] - ws.min[1], ws.max[2] - ws.min[2]];
  const centre: Vec3 = [(ws.max[0] + ws.min[0]) / 2, (ws.max[1] + ws.min[1]) / 2, (ws.max[2] + ws.min[2]) / 2];
  const edges = useMemo(() => new THREE.EdgesGeometry(new THREE.BoxGeometry(...size)), [size[0], size[1], size[2]]); // eslint-disable-line react-hooks/exhaustive-deps
  const color = estop ? C.estop : C.envelope;
  return (
    <group position={centre}>
      <lineSegments geometry={edges}>
        <lineBasicMaterial color={color} transparent opacity={estop ? 1 : 0.85} />
      </lineSegments>
      <mesh>
        <boxGeometry args={size} />
        <meshBasicMaterial color={color} transparent opacity={estop ? 0.07 : 0.028} depthWrite={false} side={THREE.DoubleSide} />
      </mesh>
      {/* footprint on the bench */}
      <mesh position={[0, 0, ws.table_z - centre[2] + 0.0012]}>
        <planeGeometry args={[size[0], size[1]]} />
        <meshBasicMaterial color={color} transparent opacity={estop ? 0.16 : 0.09} depthWrite={false} />
      </mesh>
    </group>
  );
}

function ObjectGeometry({ o }: { o: SceneObject }) {
  const [a = 0.02, b = a, c = a] = o.size;
  if (o.type === 'sphere') return <sphereGeometry args={[a, 32, 20]} />;
  if (o.type === 'cylinder') return <cylinderGeometry args={[a, a, 2 * b, 48]} />;
  return <boxGeometry args={[2 * a, 2 * b, 2 * c]} />; // box (and a mesh we cannot load yet: its bounding box)
}

function SceneObjectMesh({ o, smooth, sim }: { o: SceneObject; smooth: Smoothed; sim: boolean }) {
  const ref = useRef<THREE.Group>(null);
  useFrame(() => {
    const g = ref.current;
    const cur = smooth.objects.get(o.id);
    if (!g || !cur) return;
    // On a live robot an object is drawn only where the feed puts it; in sim the spec pose stands in.
    g.visible = cur.live || sim;
    g.position.copy(cur.p);
    g.quaternion.copy(cur.q);
  });
  const isCyl = o.type === 'cylinder';
  return (
    <group ref={ref}>
      {/* three's cylinder axis is +y; the spec's (MuJoCo's) is +z */}
      <mesh rotation={isCyl ? [Math.PI / 2, 0, 0] : [0, 0, 0]} castShadow receiveShadow>
        <ObjectGeometry o={o} />
        <meshStandardMaterial color={o.color} roughness={0.5} />
      </mesh>
      {isCyl && o.rim_color && (
        <mesh position={[0, 0, (o.size[1] ?? 0.006) + 0.004]}>
          <torusGeometry args={[o.size[0], 0.005, 10, 48]} />
          <meshStandardMaterial color={o.rim_color} roughness={0.4} />
        </mesh>
      )}
    </group>
  );
}

function Region({ r, z }: { r: SceneRegion; z: number }) {
  const color = r.color ?? C.intent;
  const w = 2 * r.size[0];
  const h = 2 * (r.size[1] ?? r.size[0]);
  const edges = useMemo(() => new THREE.EdgesGeometry(new THREE.PlaneGeometry(w, h)), [w, h]);
  return (
    <group position={[r.pos[0], r.pos[1], z + 0.0015]}>
      {r.type === 'disc' ? (
        <mesh>
          <ringGeometry args={[Math.max(0, r.size[0] - 0.004), r.size[0] + 0.004, 64]} />
          <meshBasicMaterial color={color} transparent opacity={0.75} depthWrite={false} />
        </mesh>
      ) : (
        <lineSegments geometry={edges}>
          <lineBasicMaterial color={color} transparent opacity={0.85} />
        </lineSegments>
      )}
      <mesh>
        {r.type === 'disc' ? <circleGeometry args={[r.size[0], 64]} /> : <planeGeometry args={[w, h]} />}
        <meshBasicMaterial color={color} transparent opacity={0.12} depthWrite={false} />
      </mesh>
    </group>
  );
}

function GhostPath({ rows }: { rows: number[][] }) {
  const pts = useMemo(() => rows.filter((r) => r.length >= 6 && r.slice(0, 6).every(Number.isFinite)).map((r) => KIN.graspSitePos(r)), [rows]);
  if (pts.length < 2) return null;
  return (
    <group>
      <Line points={pts} color={C.intent} lineWidth={2.2} transparent opacity={0.9} />
      {pts.map((p, i) => (
        <mesh key={i} position={p}>
          <sphereGeometry args={[i === pts.length - 1 ? 0.007 : 0.0035, 12, 8]} />
          <meshBasicMaterial color={C.intent} transparent opacity={i === pts.length - 1 ? 0.95 : 0.6} />
        </mesh>
      ))}
    </group>
  );
}

function EstopRing({ on }: { on: boolean }) {
  const ref = useRef<THREE.Mesh>(null);
  useFrame(({ clock }) => {
    if (!ref.current) return;
    ref.current.visible = on;
    const m = ref.current.material as THREE.MeshBasicMaterial;
    m.opacity = 0.55 + 0.35 * Math.sin(clock.elapsedTime * 5);
  });
  return (
    <mesh ref={ref} position={[0, 0, 0.002]}>
      <ringGeometry args={[0.075, 0.09, 64]} />
      <meshBasicMaterial color={C.estop} transparent depthWrite={false} />
    </mesh>
  );
}

// ---------------------------------------------------------------------------------------- camera rigs
function OrbitRig({ view, controlsRef, onUserMove, enabled }: {
  view: SceneCamera;
  controlsRef: MutableRefObject<CameraControls | null>;
  onUserMove: () => void;
  enabled: boolean;
}) {
  const camera = useThree((s) => s.camera) as THREE.PerspectiveCamera;
  const first = useRef(true);
  const key = JSON.stringify([view.pos, view.target, view.fovy]);
  useEffect(() => {
    const c = controlsRef.current;
    if (!c || !view.pos || !view.target) return;
    camera.fov = view.fovy;
    camera.updateProjectionMatrix();
    void c.setLookAt(...r2t(view.pos), ...r2t(view.target), !first.current);
    first.current = false;
  }, [key, camera, controlsRef]); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => {
    const c = controlsRef.current;
    if (!c) return;
    const h = () => onUserMove();
    c.addEventListener('controlstart', h);
    return () => c.removeEventListener('controlstart', h);
  }, [controlsRef, onUserMove]);
  return (
    <CameraControls
      ref={controlsRef}
      makeDefault
      enabled={enabled}
      minDistance={0.25}
      maxDistance={3.2}
      maxPolarAngle={Math.PI * 0.49}
      smoothTime={0.35}
      draggingSmoothTime={0.08}
    />
  );
}

/** Rides the D405 on the flange: the same pose and fov as the sim's `wrist` camera. */
function WristRig({ smooth, fovy, mount }: { smooth: Smoothed; fovy: number; mount: THREE.Matrix4 }) {
  const camera = useThree((s) => s.camera) as THREE.PerspectiveCamera;
  const m = useMemo(() => new THREE.Matrix4(), []);
  const site = useMemo(() => new THREE.Matrix4().compose(new THREE.Vector3(...YAM_WRIST_CAMERA.pos), quatWxyz(YAM_WRIST_CAMERA.quat), new THREE.Vector3(1, 1, 1)), []);
  useEffect(() => {
    camera.fov = fovy;
    camera.updateProjectionMatrix();
  }, [camera, fovy]);
  useFrame(() => {
    const t: Mat4 = KIN.bodyTransforms(smooth.q, smooth.gripper)[YAM_WRIST_CAMERA.body];
    m.fromArray(Array.from(t)).multiply(site).premultiply(mount).premultiply(ROBOT_TO_THREE);
    m.decompose(camera.position, camera.quaternion, camera.scale);
    camera.updateMatrixWorld();
  });
  return null;
}

// ---------------------------------------------------------------------------------------- dev probe
declare global {
  interface Window {
    __rdfTwin?: { ee: () => Vec3 | null; q: () => number[]; fps: () => number };
  }
}

function DevProbe({ graspRef, smooth }: { graspRef: MutableRefObject<THREE.Object3D | null>; smooth: Smoothed }) {
  const frames = useRef<number[]>([]);
  useFrame(() => {
    const now = performance.now();
    const f = frames.current;
    f.push(now);
    while (f.length && now - f[0] > 1000) f.shift();
  });
  useEffect(() => {
    if (process.env.NODE_ENV === 'production') return;
    const v = new THREE.Vector3();
    const probe: NonNullable<Window['__rdfTwin']> = {
      // world position of the grasp_site node in the rendered scene graph, in the world (table) frame
      ee: () => {
        const o = graspRef.current;
        if (!o) return null;
        o.getWorldPosition(v);
        return [v.x, -v.z, v.y];
      },
      q: () => [...smooth.q],
      fps: () => frames.current.length,
    };
    window.__rdfTwin = probe;
    return () => {
      if (window.__rdfTwin === probe) delete window.__rdfTwin;
    };
  }, [graspRef, smooth]);
  return null;
}

// ---------------------------------------------------------------------------------------- frame budget
/** frameloop="demand" at most `fps` frames a second (a small view does not need the display's 60). */
function Pacer({ fps }: { fps: number }) {
  const invalidate = useThree((s) => s.invalidate);
  useEffect(() => {
    let raf = 0;
    let last = 0;
    const step = 1000 / fps;
    const tick = (t: number) => {
      raf = requestAnimationFrame(tick);
      if (t - last >= step - 4) {
        last = t;
        invalidate();
      }
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [fps, invalidate]);
  return null;
}

/** R3F's shared loop stops when every canvas is paused; going back to drawing has to restart it. */
function Kick({ loop }: { loop: string }) {
  const invalidate = useThree((s) => s.invalidate);
  useEffect(() => {
    if (loop !== 'never') invalidate();
  }, [loop, invalidate]);
  return null;
}

// ---------------------------------------------------------------------------------------- component
export function RobotTwin3D({ state, camera, preset, spec, controls = true, sim = false, ghost, className, perf }: RobotTwin3DProps) {
  const stateRef = useRef<RobotLiveState | null>(state);
  stateRef.current = state;
  const ghostRows = ghost && ghost.length ? ghost : null;
  const ghostLast = ghostRows ? ghostRows[ghostRows.length - 1] : null;
  const ghostRef = useRef<number[] | null>(null);
  ghostRef.current = ghostLast && ghostLast.length >= 6 && ghostLast.slice(0, 6).every(Number.isFinite) ? ghostLast : null;

  const smooth = useMemo(newSmoothed, []);
  const graspRef = useRef<THREE.Object3D | null>(null);
  const controlsRef = useRef<CameraControls | null>(null);
  const [moved, setMoved] = useState(false);
  const [dpr, setDpr] = useState<number>(1.5);
  // Small tiles (phones, multi-view grids): cap the pixel ratio and use a lighter shadow map.
  const wrapRef = useRef<HTMLDivElement>(null);
  const [narrow, setNarrow] = useState(false);
  const maxDpr = perf?.maxDpr ?? (narrow ? 1.5 : 2);
  // Draw only while on screen and the tab is in front (a hidden view keeps its last frame, costs nothing).
  const [onScreen, setOnScreen] = useState(true);
  const pageVisible = usePageVisible();
  useEffect(() => {
    const el = wrapRef.current;
    if (!el) return;
    const ro = new ResizeObserver(([e]) => setNarrow(e.contentRect.width < 720));
    ro.observe(el);
    const io = typeof IntersectionObserver === 'undefined' ? null : new IntersectionObserver(([e]) => setOnScreen(e.isIntersecting), { rootMargin: '64px' });
    io?.observe(el);
    return () => {
      ro.disconnect();
      io?.disconnect();
    };
  }, []);
  useEffect(() => setDpr(Math.min(maxDpr, window.devicePixelRatio || 1)), [maxDpr]);
  const frameloop: 'always' | 'demand' | 'never' = !onScreen || !pageVisible ? 'never' : perf?.maxFps ? 'demand' : 'always';
  const shadowsOn = perf ? perf.shadows : true;
  const shadowMap = perf?.shadowMapSize ?? (narrow ? 1024 : 2048);
  const blurSamples = perf?.blurSamples || (narrow ? 8 : 16);
  const glOpts = useMemo(() => ({ antialias: true, powerPreference: 'high-performance' as const }), []);
  const view = resolveTwinCamera(camera ?? preset, spec);
  const wrist = view.attach === 'wrist';
  useEffect(() => setMoved(false), [view.id]);

  // Values the scene graph depends on, kept referentially stable so a new state sample (10-30 Hz) does not
  // re-render the whole three.js tree: per-frame motion is read from refs by Driver / Arm / WristRig.
  const wsRaw = state?.workspace;
  const wsKey = wsRaw ? JSON.stringify([wsRaw.min, wsRaw.max, wsRaw.table_z]) : '';
  const ws = useMemo(() => wsRaw, [wsKey]); // eslint-disable-line react-hooks/exhaustive-deps
  const estop = !!state?.estop;
  const mats = useArmMaterials();

  // What to draw: the spec, else the legacy cube / plate the feed carries.
  const live = sceneLive(state);
  const legacyKey = live ? [live.cube ? 'cube' : '', live.plate ? 'plate' : '', ...Object.keys(live.objects ?? {})].join(',') : '';
  const scene = useMemo(() => spec ?? legacyScene(live), [spec, legacyKey]); // eslint-disable-line react-hooks/exhaustive-deps
  const objects = useMemo(() => scene?.objects ?? [], [scene]);
  const objectsRef = useRef<SceneObject[]>(objects);
  objectsRef.current = objects;
  useEffect(() => {
    // a new spec: forget poses of objects it no longer has, re-seed from the spec on the next frame
    const ids = new Set(objects.map((o) => o.id));
    for (const id of [...smooth.objects.keys()]) if (!ids.has(id)) smooth.objects.delete(id);
  }, [objects, smooth]);
  const table: SceneTable = useMemo(() => spec?.table ?? { ...DEFAULT_TABLE, top_z: ws?.table_z ?? 0 }, [spec?.table, ws?.table_z]);
  const mount = spec?.robot.mount;
  const mountPos = useMemo(() => (mount?.pos ?? [0, 0, 0]) as [number, number, number], [mount?.pos]);
  const mountQuat = useMemo(() => quatWxyz(mount?.quat ?? [1, 0, 0, 0]), [mount?.quat]);
  const mountM = useMemo(() => new THREE.Matrix4().compose(new THREE.Vector3(...mountPos), mountQuat, new THREE.Vector3(1, 1, 1)), [mountPos[0], mountPos[1], mountPos[2], mountQuat]); // eslint-disable-line react-hooks/exhaustive-deps

  const onUserMove = useCallback(() => setMoved(true), []);
  const resetView = () => {
    const c = controlsRef.current;
    if (!c || wrist || !view.pos || !view.target) return;
    void c.setLookAt(...r2t(view.pos), ...r2t(view.target), true);
    setMoved(false);
  };

  // The three.js scene, memoised: it changes with the scene, the workspace, e-stop, the ghost and the view, not
  // with every state sample (motion is applied per frame from refs).
  const sceneGraph = useMemo(
    () => (
      <>
        <color attach="background" args={[sim ? C.stageSim : C.stage]} />
        <fog attach="fog" args={[sim ? C.stageSim : C.stage, 2.4, 7.5]} />

        <hemisphereLight args={['#dfe7f2', '#2b2f36', 0.4]} />
        <directionalLight
          position={r2t([0.6, -0.6, 1.6])}
          intensity={2.8}
          castShadow={shadowsOn}
          shadow-mapSize={[shadowMap, shadowMap]}
          shadow-camera-left={-0.8}
          shadow-camera-right={0.8}
          shadow-camera-top={0.8}
          shadow-camera-bottom={-0.8}
          shadow-camera-near={0.2}
          shadow-camera-far={4}
          shadow-radius={9}
          shadow-blurSamples={blurSamples}
          shadow-bias={-0.0006}
        />
        <directionalLight position={r2t([-0.5, 0.7, 0.9])} intensity={0.5} color="#c9d6ff" />

        <Environment resolution={128} frames={1}>
          <Lightformer form="rect" intensity={2.2} position={[0, 3, 0]} rotation={[Math.PI / 2, 0, 0]} scale={[4, 4, 1]} />
          <Lightformer form="rect" intensity={1.4} color="#ffe9cf" position={[3, 1.2, 1.5]} rotation={[0, -Math.PI / 2.4, 0]} scale={[2.5, 1, 1]} />
          <Lightformer form="rect" intensity={0.9} color="#cfe0ff" position={[-3, 1, -1]} rotation={[0, Math.PI / 2.2, 0]} scale={[3, 0.6, 1]} />
          <Lightformer form="ring" intensity={0.6} position={[0, 1, -4]} scale={2} />
        </Environment>

        <Driver stateRef={stateRef} ghostRef={ghostRef} smooth={smooth} objectsRef={objectsRef} />
        <Bench table={table} sim={sim} />

        {/* world (table) frame, z up */}
        <group rotation={[-Math.PI / 2, 0, 0]}>
          {(scene?.regions ?? []).map((r) => (
            <Region key={r.id} r={r} z={table.top_z} />
          ))}
          {objects.map((o) => (
            <SceneObjectMesh key={o.id} o={o} smooth={smooth} sim={sim} />
          ))}
          {/* robot base frame */}
          <group position={mountPos} quaternion={mountQuat}>
            <Suspense fallback={null}>
              <Arm read={() => ({ q: smooth.q, gripper: smooth.gripper })} materials={mats.solid} graspRef={graspRef} shadows={shadowsOn} />
              {ghostRows && <Arm read={() => (smooth.ghostQ ? { q: smooth.ghostQ, gripper: smooth.gripper } : null)} materials={mats.ghost} shadows={false} only={GHOST_BODIES} />}
            </Suspense>
            {ws && <Envelope ws={ws} estop={estop} />}
            <EstopRing on={estop} />
            {ghostRows && <GhostPath rows={ghostRows} />}
          </group>
        </group>

        {wrist ? (
          <WristRig smooth={smooth} fovy={view.fovy} mount={mountM} />
        ) : (
          <OrbitRig view={view} controlsRef={controlsRef} onUserMove={onUserMove} enabled={controls} />
        )}
        <DevProbe graspRef={graspRef} smooth={smooth} />
      </>
    ),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [sim, table, scene, objects, mountPos, mountQuat, mountM, ws, estop, ghostRows, view, wrist, controls, mats, shadowsOn, shadowMap, blurSamples, onUserMove],
  );

  return (
    <div
      ref={wrapRef}
      className={`relative h-full w-full select-none ${className ?? ''}`}
      role="img"
      aria-label={`3D view of the YAM arm${state ? '' : ' (no joint state yet, shown at rest)'}${estop ? ', e-stop engaged' : ''}`}
      data-twin-ready={state ? 'live' : 'rest'}
    >
      <Canvas
        // shadows on/off and the shadow-map size only take effect on a fresh renderer
        key={`${shadowsOn ? 's' : 'n'}${shadowMap}`}
        shadows={shadowsOn ? 'variance' : false}
        dpr={dpr}
        frameloop={frameloop}
        gl={glOpts}
        camera={{ fov: view.fovy, near: 0.01, far: 30, position: r2t(view.pos ?? TWIN_CAMERAS.top.pos!) }}
        style={{ touchAction: wrist || !controls ? 'auto' : 'none' }}
        data-frameloop={frameloop}
      >
        <PerformanceMonitor onDecline={() => setDpr(Math.min(1, maxDpr))} onIncline={() => setDpr(Math.min(maxDpr, window.devicePixelRatio || 1))} />
        <Kick loop={frameloop} />
        {frameloop === 'demand' && perf?.maxFps ? <Pacer fps={perf.maxFps} /> : null}
        {sceneGraph}
      </Canvas>

      {moved && controls && !wrist && (
        <button
          type="button"
          onClick={resetView}
          className="absolute right-2 top-11 rounded-md bg-black/45 px-2.5 py-1 text-xs font-medium text-white/90 backdrop-blur-sm hover:bg-black/60 focus-visible:outline focus-visible:outline-2 focus-visible:outline-white"
        >
          Reset view
        </button>
      )}
    </div>
  );
}

useGLTF.preload(GLB_URL);

export default RobotTwin3D;
